def solve(N,M,A,B,C):
    dp = [float('Inf') for _ in range(2**N)]
    dp[0] = 0

    def f(C):
        return(sum(map(lambda x:2**(x-1),C)))

    for i in range(1,M+1):
        c = f(C[i-1])
        for d in range(0,2**N):
            dp[d | c] = min(dp[d | c], dp[d] + A[i-1])

    print(dp[-1] if dp[-1] != float("inf") else -1)





